import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.LJP3gfxI.js";const u=JSON.parse('{"title":"Exact Interface contracts (interfaces.takoform.com/v1alpha1)","description":"","frontmatter":{},"headers":[],"relativePath":"spec/interface-contract/index.md","filePath":"spec/interface-contract/index.md"}'),n={name:"spec/interface-contract/index.md"};function o(r,e,h,c,d,l){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="exact-interface-contracts-interfaces-takoform-com-v1alpha1" tabindex="-1">Exact Interface contracts (interfaces.takoform.com/v1alpha1) <a class="header-anchor" href="#exact-interface-contracts-interfaces-takoform-com-v1alpha1" aria-label="Permalink to &quot;Exact Interface contracts (interfaces.takoform.com/v1alpha1)&quot;">​</a></h1><p>An Interface is a repository-distributed, digest-bound contract for one portable operation surface. It replaces the open <code>(name, version, operations)</code> descriptors of the retained v1alpha2 lane for all new-lane Forms (<a href="./../decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). The retained projection contract remains documented in <a href="./../interface-declaration/"><code>../interface-declaration/</code></a> for the frozen lanes.</p><h2 id="interfaceref" tabindex="-1">InterfaceRef <a class="header-anchor" href="#interfaceref" aria-label="Permalink to &quot;InterfaceRef&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;interfaces.takoform.com/v1alpha1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.kv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>name</code> uses the dotted grammar <code>^[a-z][a-z0-9]*(?:\\.[a-z][a-z0-9]*)*$</code> (max 128). Segments are lowercase alphanumeric; a hyphen is invalid here, so an Interface name never mirrors a hyphenated Binding name such as <code>module-worker.service</code>. The Edge Platform Family&#39;s worker-scoped contracts are therefore <code>worker.service</code> and <code>worker.runtime</code>.</li><li><code>version</code> is SemVer.</li><li><code>schemaDigest</code> is the RFC 8785 canonical digest of the Interface Definition bytes. Two definitions with different canonical bytes are different Interfaces even under one display name.</li></ul><p>The normative shape is <a href="/schemas/interfaces/v1alpha1/interface-ref.schema.json"><code>../schemas/interface-ref-v1alpha1.schema.json</code></a>.</p><h2 id="interface-definition" tabindex="-1">Interface Definition <a class="header-anchor" href="#interface-definition" aria-label="Permalink to &quot;Interface Definition&quot;">​</a></h2><p>The normative shape is <a href="/schemas/interfaces/v1alpha1/interface-definition.schema.json"><code>../schemas/interface-definition-v1alpha1.schema.json</code></a>. A definition MUST fix, as data only:</p><ul><li><code>operations[]</code>: name, input schema, output schema, and a closed <code>errors[]</code> vocabulary per operation;</li><li><code>semantics</code>: the consistency model and pagination contract the whole surface obeys — closed enums, not free tokens.</li></ul><p>A definition SHOULD also declare, and MAY omit (both fields are OPTIONAL in the schema, and the schema wins per <a href="./../conformance.html"><code>../conformance.md</code></a>):</p><ul><li><code>limits</code>: portable minimum limits every conforming host MUST accept when the definition declares them;</li><li><code>fixtures[]</code>: declarative behavior traces (see below).</li></ul><p>A definition MUST NOT contain executable code, credentials, endpoints, prices, or host identities; the Form Package data-only policy applies unchanged.</p><p>Rules that are behavioral rather than structural — what an uncaught exception does, whether a body streams, what keeps an isolate alive — are stated as normative sentences in the definition&#39;s own <code>description</code> and per-operation <code>description</code>, and proven by fixtures wherever a fixture can prove them. That is the placement rule of <a href="./../decisions/0014-published-schemas-are-structural-minima.html">decision 0014</a>: the published meta-schema is a structural minimum, so a contract expresses everything it can within what that schema already admits rather than minting a new identity for each new kind of rule. <code>worker.runtime@1.0.0</code> is the worked example (<a href="./../decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>).</p><h2 id="runtime-abis-are-interfaces-too" tabindex="-1">Runtime ABIs are Interfaces too <a class="header-anchor" href="#runtime-abis-are-interfaces-too" aria-label="Permalink to &quot;Runtime ABIs are Interfaces too&quot;">​</a></h2><p>An Interface is not only a capability a resource offers outward. The exact runtime a host provides to code it runs is the same kind of contract, and is declared the same way: <code>ModuleWorker</code> lists <code>worker.runtime@1.0.0</code> in its <code>providedInterfaces</code>, a host that supports that Form implements the contract at that exact digest, and a runtime revision is a new contract version rather than a new value of some field. A Form MUST NOT state a runtime by a version token, date, or flag whose meaning depends on a registry the specification does not publish.</p><p>A runtime contract is verified in two places, and neither substitutes for the other. The Host API conformance lane drives desired state, so it proves what a host SAYS and what it REFUSES: the exact advertised digest, the closed handler vocabulary, and that a Worker Version declaring a handler the ABI does not define — or one the module it references does not export — is refused before anything is stored. Everything the contract fixes about invocation is proven by its behavior fixtures against a real isolate: handler signatures, streaming bodies, <code>env</code>&#39;s exact property set, <code>waitUntil</code>, exception outcomes, and the <code>globals</code> floor. The exact split for <code>worker.runtime@1.0.0</code> is written down in <a href="./../host-api/v1beta1.html#what-the-lane-proves-and-what-stays-a-host-obligation"><code>../host-api/v1beta1.md</code></a>, because a reader deciding whether a passing conformance report means &quot;this host runs my code correctly&quot; is entitled to know which half it covers.</p><p>The second half has its own corpus, runner, and command — <a href="../../conformance/runtime-abi-v1/contract.json"><code>../../conformance/runtime-abi-v1/</code></a>, driven against a worker deployed from its own byte-pinned bundle rather than against a Host API (<a href="./../decisions/0023-the-runtime-abi-is-measured-separately-from-the-control-plane.html">decision 0023</a>). Its reports state which subject was measured: a run against the repository&#39;s in-process stand-in proves the corpus, only a run against a deployed worker proves a runtime, and neither is ever publication evidence. Every handler <code>worker.runtime@1.0.0</code> declares is measured there, and the corpus ENFORCES that rather than stating it: a declared handler with no check naming it is refused at load, and an explicitly unmeasured entry does not discharge one. A handler nothing can invoke is therefore removed from the contract and returns with the attachment that makes it observable, in a new exact version (<a href="./../decisions/0019-the-module-worker-abi-is-an-exact-contract.html">decision 0019</a>). An operation that genuinely cannot be observed may still be recorded as unmeasured with what would close it, which is what the load lane reports when a run has no module-loader adapter.</p><h2 id="behavior-fixtures" tabindex="-1">Behavior fixtures <a class="header-anchor" href="#behavior-fixtures" aria-label="Permalink to &quot;Behavior fixtures&quot;">​</a></h2><p>Shape validation alone cannot distinguish a KV store from a queue, so an Interface Definition SHOULD carry data-only traces. This one belongs to <code>edge.objects</code>, whose declared consistency is <code>read_after_write</code>, which is what makes the second step&#39;s expectation normative:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;put-then-head-observes-the-write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;steps&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;operation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;put&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;bodyStream&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;contentLength&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;operation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;head&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;expected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A conforming implementation executes each trace in order against one fresh scope and MUST produce outputs matching every <code>expected</code> clause. Properties that are not deterministically observable from one client (for example cross-location convergence of an eventually consistent store) are out of fixture scope and belong to distributed conformance runs, not packages.</p><p>A fixture set MUST NOT contradict the <code>semantics</code> of the definition that carries it. The rule is easy to break in exactly one direction — writing the trace an implementation &quot;obviously&quot; satisfies — and <code>edge.kv</code> broke it: it declared <code>consistency: eventual</code> while requiring a put to be visible to the very next get, which is the one trace a correct eventually consistent store is allowed to fail. A trace no conforming implementation can pass is the same defect as a required conformance check no correct host can complete, and the fix is the same both times: keep the semantics, remove the trace, and state the unprovable half as a host obligation (<a href="./../decisions/0020-the-edge-interfaces-state-their-data-and-delivery-model.html">decision 0020</a>). A fixture whose <code>expectedError</code> is outside the closed <code>errors</code> vocabulary of the operation it exercises is unpassable for the same reason, and the family catalog refuses to render one.</p><p>Where a value is bytes, the contract carries it in one shared encoded-bytes shape rather than as a bare string, so that a declared byte limit and a structural <code>maxLength</code> do not measure two different quantities. Where a payload streams at all — an object body, a worker-to-worker request or response — the operation declares that it streams and states what is KNOWN of its length instead of carrying the bytes, and the bytes travel beside the document. What is known is sometimes nothing: a <code>worker.service</code> call completes at the response head, so a body generated as it is written has no byte count to state there, and a contract that demanded one would have bought it by buffering the body — the defect streaming exists to avoid. Its <code>contentLength</code> is therefore nullable in both directions, an integer being an exact count the writer knows and <code>null</code> a count it does not have. A contract that streams also has to say what a caller can OBSERVE about the stream: whether an absent body differs from an empty one and from one of unknown length, what a declared count obliges when the bytes disagree with it, when the stream starts, how backpressure and cancellation behave, and how a truncation on each side is reported. <code>worker.service@1.0.0</code> is the worked example, and its first version is the counter-example — it declared bodies as JSON strings while the binding that projects it promised streaming, so the two halves of one contract disagreed. All of it is decided in decision 0020 and stated in each definition&#39;s own descriptions, because the published meta-schema has a member for none of it.</p><p><code>edge.sql</code> uses the same encoded-bytes object for BLOBs but does not expose SQLite storage-class tags. Its exact value is null, a finite binary64 number inside <code>Number.MAX_SAFE_INTEGER</code>, UTF-8 text, or canonical encoded bytes. <code>query</code> earns idempotency by executing inside a rollback-only transaction and always rolling it back, not by classifying SQL text as read-only; runtime SQL cannot own schema migration. That correction supersedes only decision 0020&#39;s SQL portions (<a href="./../decisions/0034-edge-sql-uses-safe-wire-values-and-rollback-only-queries.html">decision 0034</a>).</p><h2 id="interface-distribution" tabindex="-1">Interface distribution <a class="header-anchor" href="#interface-distribution" aria-label="Permalink to &quot;Interface distribution&quot;">​</a></h2><p>Interface candidates are distributed as digest-bound Interface Definition documents in the repository&#39;s <code>interfaces/candidates/v1alpha1</code> directory; the exact InterfaceRef with its <code>schemaDigest</code> is the immutable reference. They are not independently installable third-party artifacts, and no Interface Package envelope identity exists, is specified, or is published: the envelope was withdrawn, not deferred (<a href="./../decisions/0021-third-party-forms-and-contract-distribution.html">decision 0021</a>). A <code>schemaDigest</code> therefore binds the canonical Definition bytes and says nothing about where they came from — no package digest, no publisher identity, no signature, no revocation feed — so a host obtains these contracts the way it obtains any other part of this specification.</p><h2 id="relationship-to-forms-and-bindings" tabindex="-1">Relationship to Forms and Bindings <a class="header-anchor" href="#relationship-to-forms-and-bindings" aria-label="Permalink to &quot;Relationship to Forms and Bindings&quot;">​</a></h2><ul><li>A Form Definition lists the Interfaces its resources provide as exact <code>providedInterfaces[]</code> refs.</li><li>A Binding contract names the Interface its target must provide as an exact ref; a host resolving a binding MUST verify the target Form provides that Interface.</li><li>Hosts advertise which Interfaces they implement, and within which limits, in their Host Support Profile — never inside the Interface Definition.</li></ul>`,28)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
